"use client";

import { PropsWithChildren, useEffect, useState, type FC } from "react";
import Image from "next/image";
import { XIcon, PlusIcon, FileText } from "lucide-react";
import {
  AttachmentPrimitive,
  ComposerPrimitive,
  MessagePrimitive,
  useAssistantState,
  useAssistantApi,
} from "@assistant-ui/react";
import { useShallow } from "zustand/shallow";
import {
  Tooltip,
  TooltipContent,
  TooltipTrigger,
} from "@/components/ui/tooltip";
import {
  Dialog,
  DialogTitle,
  DialogContent,
  DialogTrigger,
} from "@/components/ui/dialog";
import { Avatar, AvatarImage, AvatarFallback } from "@/components/ui/avatar";
import { TooltipIconButton } from "@/components/assistant-ui/tooltip-icon-button";
import { cn } from "@/lib/utils";

const useFileSrc = (file: File | undefined) => {
  const [src, setSrc] = useState<string | undefined>(undefined);

  useEffect(() => {
    if (!file) {
      setSrc(undefined);
      return;
    }

    const objectUrl = URL.createObjectURL(file);
    setSrc(objectUrl);

    return () => {
      URL.revokeObjectURL(objectUrl);
    };
  }, [file]);

  return src;
};

const useAttachmentSrc = () => {
  const { file, src } = useAssistantState(
    useShallow(({ attachment }): { file?: File; src?: string } => {
      if (attachment.type !== "image") return {};
      if (attachment.file) return { file: attachment.file };
      const src = attachment.content?.filter((c) => c.type === "image")[0]
        ?.image;
      if (!src) return {};
      return { src };
    }),
  );

  return useFileSrc(file) ?? src;
};

type AttachmentPreviewProps = {
  src: string;
};

const AttachmentPreview: FC<AttachmentPreviewProps> = ({ src }) => {
  return (
    <div className="relative w-full h-full min-h-[400px]">
      <Image
        src={src}
        alt="Image Preview"
        fill
        className="aui-attachment-preview-image object-contain"
        priority={false}
      />
    </div>
  );
};

const AttachmentPreviewDialog: FC<PropsWithChildren> = ({ children }) => {
  const src = useAttachmentSrc();

  if (!src) return children;

  return (
    <Dialog>
      <DialogTrigger
        className="aui-attachment-preview-trigger cursor-pointer transition-colors hover:bg-accent/50"
        asChild
      >
        {children}
      </DialogTrigger>
      <DialogContent className="aui-attachment-preview-dialog-content p-2 sm:max-w-3xl [&_svg]:text-background [&>button]:rounded-full [&>button]:bg-foreground/60 [&>button]:p-1 [&>button]:opacity-100 [&>button]:!ring-0 [&>button]:hover:[&_svg]:text-destructive">
        <DialogTitle className="aui-sr-only sr-only">
          Image Attachment Preview
        </DialogTitle>
        <div className="aui-attachment-preview relative mx-auto flex max-h-[80dvh] w-full items-center justify-center overflow-hidden bg-background">
          <AttachmentPreview src={src} />
        </div>
      </DialogContent>
    </Dialog>
  );
};

const AttachmentThumb: FC = () => {
  const isImage = useAssistantState(
    ({ attachment }) => attachment.type === "image",
  );
  const src = useAttachmentSrc();

  return (
    <Avatar className="aui-attachment-tile-avatar h-full w-full rounded-none">
      <AvatarImage
        src={src}
        alt="Attachment preview"
        className="aui-attachment-tile-image object-cover"
      />
      <AvatarFallback delayMs={isImage ? 200 : 0}>
        <FileText className="aui-attachment-tile-fallback-icon size-8 text-muted-foreground" />
      </AvatarFallback>
    </Avatar>
  );
};

const AttachmentUI: FC = () => {
  const api = useAssistantApi();
  const isComposer = api.attachment.source === "composer";

  const { isImage, fileName, fileSize } = useAssistantState(
    useShallow(({ attachment }) => ({
      isImage: attachment.type === "image",
      fileName: attachment.name || "Unknown file",
      fileSize: attachment.file?.size,
    })),
  );

  const typeLabel = useAssistantState(({ attachment }) => {
    const type = attachment.type;
    switch (type) {
      case "image":
        return "Image";
      case "document":
        return "Document";
      case "file":
        return "File";
      default:
        const _exhaustiveCheck: never = type;
        throw new Error(`Unknown attachment type: ${_exhaustiveCheck}`);
    }
  });

  const formatFileSize = (bytes: number | undefined) => {
    if (!bytes) return "";
    if (bytes < 1024) return `${bytes} B`;
    if (bytes < 1024 * 1024) return `${(bytes / 1024).toFixed(1)} KB`;
    return `${(bytes / (1024 * 1024)).toFixed(1)} MB`;
  };

  // For non-image files in messages (not composer), show file info card
  if (!isImage && !isComposer) {
    return (
      <AttachmentPrimitive.Root className="aui-attachment-root relative">
        <div className="aui-attachment-file-card flex items-center gap-3 rounded-lg border bg-muted/50 px-4 py-3 max-w-sm">
          <div className="aui-attachment-file-icon flex-shrink-0">
            <FileText className="size-8 text-muted-foreground" />
          </div>
          <div className="aui-attachment-file-info flex-1 min-w-0">
            <div className="aui-attachment-file-name text-sm font-medium truncate">
              <AttachmentPrimitive.Name />
            </div>
            {fileSize && (
              <div className="aui-attachment-file-size text-xs text-muted-foreground">
                {formatFileSize(fileSize)}
              </div>
            )}
          </div>
        </div>
      </AttachmentPrimitive.Root>
    );
  }

  // Original UI for images and composer attachments
  return (
    <Tooltip>
      <AttachmentPrimitive.Root
        className={cn(
          "aui-attachment-root relative",
          isImage &&
            "aui-attachment-root-composer only:[&>#attachment-tile]:size-24",
        )}
      >
        <AttachmentPreviewDialog>
          <TooltipTrigger asChild>
            <div
              className={cn(
                "aui-attachment-tile size-14 cursor-pointer overflow-hidden rounded-[14px] border bg-muted transition-opacity hover:opacity-75",
                isComposer &&
                  "aui-attachment-tile-composer border-foreground/20",
              )}
              role="button"
              id="attachment-tile"
              aria-label={`${typeLabel} attachment`}
            >
              <AttachmentThumb />
            </div>
          </TooltipTrigger>
        </AttachmentPreviewDialog>
        {isComposer && <AttachmentRemove />}
      </AttachmentPrimitive.Root>
      <TooltipContent side="top">
        <AttachmentPrimitive.Name />
      </TooltipContent>
    </Tooltip>
  );
};

const AttachmentRemove: FC = () => {
  return (
    <AttachmentPrimitive.Remove asChild>
      <TooltipIconButton
        tooltip="Remove file"
        className="aui-attachment-tile-remove absolute top-1.5 right-1.5 size-3.5 rounded-full bg-white text-muted-foreground opacity-100 shadow-sm hover:!bg-white [&_svg]:text-black hover:[&_svg]:text-destructive"
        side="top"
      >
        <XIcon className="aui-attachment-remove-icon size-3 dark:stroke-[2.5px]" />
      </TooltipIconButton>
    </AttachmentPrimitive.Remove>
  );
};

export const UserMessageAttachments: FC = () => {
  return (
    <div className="aui-user-message-attachments-end col-span-full col-start-2 row-start-1 flex w-full flex-row justify-end gap-2 mb-2">
      <MessagePrimitive.Attachments components={{ Attachment: AttachmentUI }} />
    </div>
  );
};

export const ComposerAttachments: FC = () => {
  return (
    <div className="aui-composer-attachments mb-2 flex w-full flex-row items-center gap-2 overflow-x-auto px-1.5 pt-0.5 pb-1 empty:hidden">
      <ComposerPrimitive.Attachments
        components={{ Attachment: AttachmentUI }}
      />
    </div>
  );
};

export const ComposerAddAttachment: FC = () => {
  return (
    <ComposerPrimitive.AddAttachment asChild>
      <TooltipIconButton
        tooltip="Add Attachment"
        side="bottom"
        variant="ghost"
        size="icon"
        className="aui-composer-add-attachment size-[34px] rounded-full p-1 text-xs font-semibold hover:bg-muted-foreground/15 dark:border-muted-foreground/15 dark:hover:bg-muted-foreground/30"
        aria-label="Add Attachment"
      >
        <PlusIcon className="aui-attachment-add-icon size-5 stroke-[1.5px]" />
      </TooltipIconButton>
    </ComposerPrimitive.AddAttachment>
  );
};

"use client";

import "@assistant-ui/react-markdown/styles/dot.css";

import {
  type CodeHeaderProps,
  MarkdownTextPrimitive,
  unstable_memoizeMarkdownComponents as memoizeMarkdownComponents,
  useIsMarkdownCodeBlock,
} from "@assistant-ui/react-markdown";
import { useThreadRuntime, useMessage } from "@assistant-ui/react";
import remarkGfm from "remark-gfm";
import rehypeRaw from "rehype-raw";
import ReactMarkdown from "react-markdown";
import { type FC, memo, useState } from "react";
import { CheckIcon, CopyIcon } from "lucide-react";
import { visit } from "unist-util-visit";
import type { Plugin } from "unified";

import { TooltipIconButton } from "@/components/assistant-ui/tooltip-icon-button";
import { cn } from "@/lib/utils";

import { BlockRenderer, BlockSkeleton } from "@/components/tool-ui/block-renderer";
import { blockLanguages } from "@/components/tool-ui/registry";

// Remark plugin: a fenced block whose language is a known block name
// (```plan, ```chart, ...) becomes an <answer-block> element instead of code.
const remarkAnswerBlocks: Plugin = () => {
  return (tree: any) => {
    visit(tree, "code", (node: any, index: number | undefined, parent: any) => {
      const language = node.lang;

      if (blockLanguages.includes(language) && index !== undefined && parent) {
        // btoa keeps the JSON intact through the HTML attribute
        const encodedContent = btoa(encodeURIComponent(node.value));

        parent.children[index] = {
          type: "html",
          value: `<answer-block data-type="${language}" data-content="${encodedContent}"></answer-block>`,
        };
      }
    });
  };
};

// Preprocess markdown to unescape any escaped backticks
const preprocessMarkdown = (text: string): string => {
  // Unescape backticks that were escaped in JSON responses
  return text.replace(/\\`/g, '`');
};

const MarkdownTextImpl = ({ text }: { text?: string }) => {
  // If text prop is provided, use ReactMarkdown directly
  if (text !== undefined) {
    const processedText = preprocessMarkdown(text);
    return (
      <div className="aui-md">
        <ReactMarkdown
          remarkPlugins={[remarkGfm, remarkAnswerBlocks]}
          rehypePlugins={[rehypeRaw as any]}
          components={defaultComponents as any}
        >
          {processedText}
        </ReactMarkdown>
      </div>
    );
  }

  // Otherwise, get text from context using MarkdownTextPrimitive
  return (
    <MarkdownTextPrimitive
      remarkPlugins={[remarkGfm, remarkAnswerBlocks]}
      rehypePlugins={[rehypeRaw]}
      className="aui-md"
      components={defaultComponents}
      preprocess={preprocessMarkdown}
    />
  );
};

export const MarkdownText = memo(MarkdownTextImpl);

const CodeHeader: FC<CodeHeaderProps> = ({ language, code }) => {
  const { isCopied, copyToClipboard } = useCopyToClipboard();
  const onCopy = () => {
    if (!code || isCopied) return;
    copyToClipboard(code);
  };

  return (
    <div className="aui-code-header-root mt-4 flex items-center justify-between gap-4 rounded-t-lg bg-muted-foreground/15 px-4 py-2 text-sm font-semibold text-foreground dark:bg-muted-foreground/20">
      <span className="aui-code-header-language lowercase [&>span]:text-xs">
        {language}
      </span>
      <TooltipIconButton tooltip="Copy" onClick={onCopy}>
        {!isCopied && <CopyIcon />}
        {isCopied && <CheckIcon />}
      </TooltipIconButton>
    </div>
  );
};

const useCopyToClipboard = ({
  copiedDuration = 3000,
}: {
  copiedDuration?: number;
} = {}) => {
  const [isCopied, setIsCopied] = useState<boolean>(false);

  const copyToClipboard = (value: string) => {
    if (!value) return;

    navigator.clipboard.writeText(value).then(() => {
      setIsCopied(true);
      setTimeout(() => setIsCopied(false), copiedDuration);
    });
  };

  return { isCopied, copyToClipboard };
};

// Connects a block to the conversation it was rendered in
const ThreadBlock: FC<{ type: string; code: string }> = ({ type, code }) => {
  const threadRuntime = useThreadRuntime();
  const message = useMessage();

  const messages = threadRuntime.getState().messages;
  const isLatest = messages[messages.length - 1]?.id === message?.id;
  const isStreaming = message?.status?.type === "running";

  const send = (text: string) => {
    threadRuntime.append({
      role: "user",
      content: [{ type: "text", text }],
    });
  };

  return (
    <BlockRenderer
      type={type}
      code={code}
      send={send}
      isLatest={isLatest}
      // Half-written JSON while the answer streams: hold the space
      fallback={isStreaming ? <BlockSkeleton className="my-4" /> : null}
    />
  );
};

const defaultComponents = memoizeMarkdownComponents({
  // @ts-expect-error - custom HTML element from the remark plugin
  "answer-block": function AnswerBlock(props: any) {
    const type = props["data-type"];
    const encodedContent = props["data-content"];

    if (!type || !encodedContent) {
      return null;
    }

    let code: string;
    try {
      code = decodeURIComponent(atob(encodedContent));
    } catch {
      return null;
    }

    return <ThreadBlock type={type} code={code} />;
  },
  h1: ({ className, ...props }) => (
    <h1
      className={cn(
        "aui-md-h1 mb-8 scroll-m-20 text-4xl font-extrabold tracking-tight last:mb-0",
        className,
      )}
      {...props}
    />
  ),
  h2: ({ className, ...props }) => (
    <h2
      className={cn(
        "aui-md-h2 mt-8 mb-4 scroll-m-20 text-3xl font-semibold tracking-tight first:mt-0 last:mb-0",
        className,
      )}
      {...props}
    />
  ),
  h3: ({ className, ...props }) => (
    <h3
      className={cn(
        "aui-md-h3 mt-6 mb-4 scroll-m-20 text-2xl font-semibold tracking-tight first:mt-0 last:mb-0",
        className,
      )}
      {...props}
    />
  ),
  h4: ({ className, ...props }) => (
    <h4
      className={cn(
        "aui-md-h4 mt-6 mb-4 scroll-m-20 text-xl font-semibold tracking-tight first:mt-0 last:mb-0",
        className,
      )}
      {...props}
    />
  ),
  h5: ({ className, ...props }) => (
    <h5
      className={cn(
        "aui-md-h5 my-4 text-lg font-semibold first:mt-0 last:mb-0",
        className,
      )}
      {...props}
    />
  ),
  h6: ({ className, ...props }) => (
    <h6
      className={cn(
        "aui-md-h6 my-4 font-semibold first:mt-0 last:mb-0",
        className,
      )}
      {...props}
    />
  ),
  p: ({ className, ...props }) => (
    <p
      className={cn(
        "aui-md-p mt-5 mb-5 leading-7 first:mt-0 last:mb-0 rounded overflow-hidden",
        className,
      )}
      {...props}
    />
  ),
  a: ({ className, ...props }) => (
    <a
      className={cn(
        "aui-md-a font-medium text-primary underline underline-offset-4",
        className,
      )}
      {...props}
    />
  ),
  blockquote: ({ className, ...props }) => (
    <blockquote
      className={cn("aui-md-blockquote border-l-2 pl-6 italic", className)}
      {...props}
    />
  ),
  ul: ({ className, ...props }) => (
    <ul
      className={cn("aui-md-ul my-5 ml-6 list-disc [&>li]:mt-2", className)}
      {...props}
    />
  ),
  ol: ({ className, ...props }) => (
    <ol
      className={cn("aui-md-ol my-5 ml-6 list-decimal [&>li]:mt-2", className)}
      {...props}
    />
  ),
  hr: ({ className, ...props }) => (
    <hr className={cn("aui-md-hr my-5 border-b", className)} {...props} />
  ),
  table: ({ className, ...props }) => (
    <table
      className={cn(
        "aui-md-table my-5 w-full border-separate border-spacing-0 overflow-y-auto",
        className,
      )}
      {...props}
    />
  ),
  th: ({ className, ...props }) => (
    <th
      className={cn(
        "aui-md-th bg-muted px-4 py-2 text-left font-bold first:rounded-tl-lg last:rounded-tr-lg [&[align=center]]:text-center [&[align=right]]:text-right",
        className,
      )}
      {...props}
    />
  ),
  td: ({ className, ...props }) => (
    <td
      className={cn(
        "aui-md-td border-b border-l px-4 py-2 text-left last:border-r [&[align=center]]:text-center [&[align=right]]:text-right",
        className,
      )}
      {...props}
    />
  ),
  tr: ({ className, ...props }) => (
    <tr
      className={cn(
        "aui-md-tr m-0 border-b p-0 first:border-t [&:last-child>td:first-child]:rounded-bl-lg [&:last-child>td:last-child]:rounded-br-lg",
        className,
      )}
      {...props}
    />
  ),
  sup: ({ className, ...props }) => (
    <sup
      className={cn("aui-md-sup [&>a]:text-xs [&>a]:no-underline", className)}
      {...props}
    />
  ),
  pre: ({ className, ...props }) => (
    <pre
      className={cn(
        "aui-md-pre overflow-x-auto  rounded-b-lg  p-4",
        className,
      )}
      {...props}
    />
  ),
  code: function Code({ className, ...props }) {
    const isCodeBlock = useIsMarkdownCodeBlock();
    return (
      <code
        className={cn(
          !isCodeBlock &&
            "aui-md-inline-code rounded border bg-muted font-semibold",
          className,
        )}
        {...props}
      />
    );
  },
  CodeHeader,
});

"use client";

import { FC, useState } from "react";
import { Avatar, AvatarImage, AvatarFallback } from "@/components/ui/avatar";
import { Badge } from "@/components/ui/badge";
import { Button } from "@/components/ui/button";
import {
  Sheet,
  SheetContent,
  SheetHeader,
  SheetTitle,
  SheetTrigger,
} from "@/components/ui/sheet";
import { FileText, ExternalLink } from "lucide-react";
import { cn } from "@/lib/utils";
import type { Source } from "@/lib/types";

interface MessageSourcesProps {
  sources: Source[];
}

// Extract domain from URL for favicon
const getDomain = (url: string): string => {
  try {
    const urlObj = new URL(url.startsWith('http') ? url : `https://${url}`);
    return urlObj.hostname;
  } catch {
    return url;
  }
};

// Get favicon URL using Google's service
const getFaviconUrl = (url: string): string => {
  const domain = getDomain(url);
  return `https://www.google.com/s2/favicons?domain=${domain}&sz=32`;
};

export const MessageSources: FC<MessageSourcesProps> = ({ sources }) => {
  const [isOpen, setIsOpen] = useState(false);

  if (!sources || sources.length === 0) {
    return null;
  }

  // Get unique sources by id (avoid duplicates)
  const uniqueSources = sources.reduce((acc, source) => {
    if (!acc.find(s => s.id === source.id)) {
      acc.push(source);
    }
    return acc;
  }, [] as Source[]);

  // Limit to first 5 for compact display
  const displaySources = uniqueSources.slice(0, 5);
  const hasMore = uniqueSources.length > 5;

  return (
    <Sheet open={isOpen} onOpenChange={setIsOpen}>
      <SheetTrigger asChild>
        <Button
          variant="outline"
          size="sm"
          className={cn(
            "h-7 rounded-full px-2.5 py-1 text-xs font-semibold gap-1.5",
            "hover:bg-token-main-surface-secondary transition-colors cursor-pointer",
            "border-token-border-default bg-token-main-surface-primary",
            "mt-0 mb-0"
          )}
        >
          {/* Overlapping avatars - OpenAI style */}
          <div className="flex flex-row-reverse items-center">
            {displaySources.map((source, index) => (
              <div
                key={source.id}
                className={cn(
                  "border-token-main-surface-primary bg-token-main-surface-primary",
                  "flex items-center overflow-hidden rounded-full border-2",
                  "group-hover/footnote:border-token-main-surface-secondary",
                  "relative",
                  index > 0 && "-ms-1 first:me-0"
                )}
              >
                <Avatar className="size-3 border-0">
                  <AvatarImage
                    src={getFaviconUrl(source.url)}
                    alt={source.title}
                    className="duration-200 motion-safe:transition-opacity"
                  />
                  <AvatarFallback className="text-[10px] bg-muted">
                    <FileText className="size-4" />
                  </AvatarFallback>
                </Avatar>
              </div>
            ))}
          </div>

          <span className="text-token-text-secondary text-xs font-semibold">
            {uniqueSources.length} {uniqueSources.length === 1 ? 'Source' : 'Sources'}
          </span>
        </Button>
      </SheetTrigger>

      <SheetContent side="right" className="overflow-y-auto">
        <SheetHeader>
          <SheetTitle>Sources ({uniqueSources.length})</SheetTitle>
        </SheetHeader>

        <div className="space-y-3 p-4">
          {uniqueSources.map((source, index) => (
            <div
              key={`${source.id}-${index}`}
              className="rounded-lg border p-3 space-y-2 hover:bg-accent/50 transition-colors"
            >
              {/* Header with favicon and title */}
              <div className="flex items-start gap-2">
                <Avatar className="size-6 shrink-0 mt-0.5">
                  <AvatarImage
                    src={getFaviconUrl(source.url)}
                    alt={source.title}
                  />
                  <AvatarFallback className="text-[8px]">
                    <FileText className="size-3" />
                  </AvatarFallback>
                </Avatar>

                <div className="flex-1 min-w-0">
                  <div className="font-medium text-sm truncate">
                    {source.title}
                  </div>

                  {source.url && (
                    <a
                      href={source.url.startsWith('http')
                        ? source.url
                        : `https://${source.url}`}
                      target="_blank"
                      rel="noopener noreferrer"
                      className="text-xs text-muted-foreground hover:text-primary flex items-center gap-1 truncate mt-0.5"
                      onClick={(e) => e.stopPropagation()}
                    >
                      <span className="truncate">{getDomain(source.url)}</span>
                      <ExternalLink className="size-3 shrink-0" />
                    </a>
                  )}
                </div>
              </div>

              {/* Content snippet */}
              {source.snippet && (
                <p className="text-xs text-muted-foreground line-clamp-3 leading-relaxed">
                  {source.snippet}
                </p>
              )}

              {/* Metadata badges */}
              <div className="flex items-center gap-2 flex-wrap">
                {source.score !== undefined && (
                  <Badge variant="secondary" className="text-[10px] px-1.5 py-0 h-5">
                    Score: {(source.score * 100).toFixed(0)}%
                  </Badge>
                )}
              </div>
            </div>
          ))}
        </div>
      </SheetContent>
    </Sheet>
  );
};

"use client";

import { BrainIcon, ChevronDownIcon } from "lucide-react";
import {
  memo,
  useCallback,
  useRef,
  useState,
  type FC,
  type PropsWithChildren,
} from "react";

import {
  useScrollLock,
  useAssistantState,
  type ReasoningMessagePartComponent,
  type ReasoningGroupComponent,
} from "@assistant-ui/react";

import { MarkdownText } from "@/components/assistant-ui/markdown-text";
import {
  Collapsible,
  CollapsibleContent,
  CollapsibleTrigger,
} from "@/components/ui/collapsible";
import { cn } from "@/lib/utils";

const ANIMATION_DURATION = 200;
const SHIMMER_DURATION = 1000;

/**
 * Root collapsible container that manages open/closed state and scroll lock.
 * Provides animation timing via CSS variable and prevents scroll jumps on collapse.
 */
const ReasoningRoot: FC<
  PropsWithChildren<{
    className?: string;
  }>
> = ({ className, children }) => {
  const collapsibleRef = useRef<HTMLDivElement>(null);
  const [isOpen, setIsOpen] = useState(false);
  const lockScroll = useScrollLock(collapsibleRef, ANIMATION_DURATION);

  const handleOpenChange = useCallback(
    (open: boolean) => {
      if (!open) {
        lockScroll();
      }
      setIsOpen(open);
    },
    [lockScroll],
  );

  return (
    <Collapsible
      ref={collapsibleRef}
      open={isOpen}
      onOpenChange={handleOpenChange}
      className={cn("aui-reasoning-root mb-4 w-full", className)}
      style={
        {
          "--animation-duration": `${ANIMATION_DURATION}ms`,
          "--shimmer-duration": `${SHIMMER_DURATION}ms`,
        } as React.CSSProperties
      }
    >
      {children}
    </Collapsible>
  );
};

