  const cameraRef = useRef<THREE.PerspectiveCamera | null>(null);
  const micPointsRef = useRef<THREE.Points | null>(null);
  const ttsPointsRef = useRef<THREE.Points | null>(null);
  const micBasePositionsRef = useRef<Float32Array | null>(null);
  const ttsBasePositionsRef = useRef<Float32Array | null>(null);
  const animationFrameRef = useRef<number | null>(null);
  const timeRef = useRef(0);
  const {
    audioContextRef,
    analyserRef,
    stopListeningMode,
    pauseListening,
    resumeListening,
    recordingState,
    hasRecording
  } = useVoiceRecorderContext();

  useEffect(() => {
    if (!open || !containerRef.current) return;

    const container = containerRef.current;
    const micAnalyser = analyserRef.current;
    const ttsAnalyser = ttsAnalyserRef.current;

    // Setup Three.js scene
    const scene = new THREE.Scene();
    sceneRef.current = scene;

    const camera = new THREE.PerspectiveCamera(75, 1, 0.1, 1000);
    camera.position.z = 3;
    cameraRef.current = camera;

    const renderer = new THREE.WebGLRenderer({ alpha: true, antialias: true });
    const size = Math.min(container.clientWidth, container.clientHeight);
    renderer.setSize(size, size);
    renderer.setClearColor(0x000000, 0);
    container.appendChild(renderer.domElement);
    rendererRef.current = renderer;

    // Create point cloud spheres
    const createPointSphere = (color: number, count: number = 3000) => {
      const geometry = new THREE.BufferGeometry();
      const positions = new Float32Array(count * 3);
      const randomOffsets = new Float32Array(count * 3);
      const sizes = new Float32Array(count);
      const opacityFactors = new Float32Array(count);

      // Generate points on a sphere using Fibonacci sphere algorithm
      const phi = Math.PI * (3 - Math.sqrt(5)); // Golden angle

      for (let i = 0; i < count; i++) {
        const y = 1 - (i / (count - 1)) * 2;
        const radius = Math.sqrt(1 - y * y);
        const theta = phi * i;

        const x = Math.cos(theta) * radius;
        const z = Math.sin(theta) * radius;

        positions[i * 3] = x;
        positions[i * 3 + 1] = y;
        positions[i * 3 + 2] = z;

        // Random offsets for wave effect
        randomOffsets[i * 3] = (Math.random() - 0.5) * 2;
        randomOffsets[i * 3 + 1] = (Math.random() - 0.5) * 2;
        randomOffsets[i * 3 + 2] = (Math.random() - 0.5) * 2;

        // Random opacity factors (0.3 to 1.0)
        opacityFactors[i] = 0.3 + Math.random() * 0.7;

        // Base size
        sizes[i] = 0.02;
      }

      geometry.setAttribute('position', new THREE.BufferAttribute(positions, 3));
      geometry.setAttribute('randomOffset', new THREE.BufferAttribute(randomOffsets, 3));
      geometry.setAttribute('size', new THREE.BufferAttribute(sizes, 1));
      geometry.setAttribute('opacityFactor', new THREE.BufferAttribute(opacityFactors, 1));

      const material = new THREE.PointsMaterial({
        color,
        size: 0.02,
        transparent: true,
        opacity: 0.6,
        blending: THREE.AdditiveBlending,
        sizeAttenuation: true,
      });

      return { points: new THREE.Points(geometry, material), basePositions: positions.slice() };
    };

    // Create mic and TTS spheres with custom colors
    const { points: micPoints, basePositions: micBase } = createPointSphere(0x01A5C0); // Blue for mic
    const { points: ttsPoints, basePositions: ttsBase } = createPointSphere(0xB71858); // Red for TTS
    scene.add(micPoints);
    scene.add(ttsPoints);
    micPointsRef.current = micPoints;
    ttsPointsRef.current = ttsPoints;
    micBasePositionsRef.current = micBase;
    ttsBasePositionsRef.current = ttsBase;

    const micBufferLength = micAnalyser?.frequencyBinCount || 128;
    const micDataArray = new Uint8Array(micBufferLength);
    const ttsBufferLength = ttsAnalyser?.frequencyBinCount || 128;
    const ttsDataArray = new Uint8Array(ttsBufferLength);

    // Animation loop
    const animate = () => {
      animationFrameRef.current = requestAnimationFrame(animate);
      timeRef.current += 0.025;

      // Get audio data
      let micAverage = 0;
      let ttsAverage = 0;

      if (micAnalyser) {
        micAnalyser.getByteFrequencyData(micDataArray);
        micAverage = micDataArray.reduce((a, b) => a + b) / micBufferLength / 255;
      }

      if (ttsAnalyser) {
        ttsAnalyser.getByteFrequencyData(ttsDataArray);
        ttsAverage = ttsDataArray.reduce((a, b) => a + b) / ttsBufferLength / 255;
      }

      // Each visualizer uses its own audio level
      const micAudioLevel = micAverage;
      const ttsAudioLevel = ttsAverage;

      // Opacity reacts to voice (0.2 when silent, up to 0.8 with voice)
      const micOpacity = isPaused ? 0 : 0.2 + micAudioLevel * 0.6;
      const ttsOpacity = isPaused ? 0 : 0.2 + ttsAudioLevel * 0.6;

      // Animate mic sphere
      if (micPoints && micBasePositionsRef.current) {
        const positions = micPoints.geometry.attributes.position.array as Float32Array;
        const basePositions = micBasePositionsRef.current;
        const randomOffsets = micPoints.geometry.attributes.randomOffset?.array as Float32Array;
        const sizes = micPoints.geometry.attributes.size?.array as Float32Array;
        const opacityFactors = micPoints.geometry.attributes.opacityFactor?.array as Float32Array;

        for (let i = 0; i < positions.length / 3; i++) {
          const i3 = i * 3;

          // Original sphere position
          const x = basePositions[i3];
          const y = basePositions[i3 + 1];
          const z = basePositions[i3 + 2];

          // Calculate distance from center (should be ~1.0)
          const dist = Math.sqrt(x * x + y * y + z * z);
          const nx = x / dist;
          const ny = y / dist;
          const nz = z / dist;

          // Audio-reactive scaling (0.6 = base, up to 2.1 with audio)
          const baseScale = 0.6;
          const scale = baseScale + micAudioLevel * 1.5;

          // Enhanced wave effect with multiple frequencies for more organic motion
          const wave1 = Math.sin(timeRef.current * 4 + randomOffsets[i3]) * 0.25 * micAudioLevel;
          const wave2 = Math.cos(timeRef.current * 3 + randomOffsets[i3 + 1]) * 0.2 * micAudioLevel;
          const wave3 = Math.sin(timeRef.current * 5 + randomOffsets[i3 + 2]) * 0.15 * micAudioLevel;

          // Apply scaling and wave
          const finalScale = scale + wave1 + wave2 + wave3;
          positions[i3] = nx * finalScale;
          positions[i3 + 1] = ny * finalScale;
          positions[i3 + 2] = nz * finalScale;

          // Randomized size based on audio and individual opacity factor
          const sizeWave = Math.sin(timeRef.current * 4 + randomOffsets[i3]) * 0.5 + 0.5;
          const audioSize = 0.015 + micAudioLevel * 0.025;
          sizes[i] = audioSize * opacityFactors[i] * (0.7 + sizeWave * 0.6);
        }

        micPoints.geometry.attributes.position.needsUpdate = true;
        micPoints.geometry.attributes.size.needsUpdate = true;
        (micPoints.material as THREE.PointsMaterial).opacity = micOpacity;
      }

      // Animate TTS sphere
      if (ttsPoints && ttsBasePositionsRef.current) {
        const positions = ttsPoints.geometry.attributes.position.array as Float32Array;
        const basePositions = ttsBasePositionsRef.current;
        const randomOffsets = ttsPoints.geometry.attributes.randomOffset?.array as Float32Array;
        const sizes = ttsPoints.geometry.attributes.size?.array as Float32Array;
        const opacityFactors = ttsPoints.geometry.attributes.opacityFactor?.array as Float32Array;

        for (let i = 0; i < positions.length / 3; i++) {
          const i3 = i * 3;

          const x = basePositions[i3];
          const y = basePositions[i3 + 1];
          const z = basePositions[i3 + 2];

          const dist = Math.sqrt(x * x + y * y + z * z);
          const nx = x / dist;
          const ny = y / dist;
          const nz = z / dist;

          const baseScale = 0.6;
          const scale = baseScale + ttsAudioLevel * 1.5;

          const wave1 = Math.sin(timeRef.current * 4 + randomOffsets[i3]) * 0.25 * ttsAudioLevel;
          const wave2 = Math.cos(timeRef.current * 3 + randomOffsets[i3 + 1]) * 0.2 * ttsAudioLevel;
          const wave3 = Math.sin(timeRef.current * 5 + randomOffsets[i3 + 2]) * 0.15 * ttsAudioLevel;

          const finalScale = scale + wave1 + wave2 + wave3;
          positions[i3] = nx * finalScale;
          positions[i3 + 1] = ny * finalScale;
          positions[i3 + 2] = nz * finalScale;

          // Randomized size based on audio and individual opacity factor
          const sizeWave = Math.sin(timeRef.current * 4 + randomOffsets[i3]) * 0.5 + 0.5;
          const audioSize = 0.015 + ttsAudioLevel * 0.025;
          sizes[i] = audioSize * opacityFactors[i] * (0.7 + sizeWave * 0.6);
        }

        ttsPoints.geometry.attributes.position.needsUpdate = true;
        ttsPoints.geometry.attributes.size.needsUpdate = true;
        (ttsPoints.material as THREE.PointsMaterial).opacity = ttsOpacity;
      }

      renderer.render(scene, camera);
    };

    animate();

    return () => {
      if (animationFrameRef.current) {
        cancelAnimationFrame(animationFrameRef.current);
      }
      if (renderer.domElement.parentNode) {
        renderer.domElement.parentNode.removeChild(renderer.domElement);
      }
      renderer.dispose();
      micPoints?.geometry.dispose();
      (micPoints?.material as THREE.Material)?.dispose();
      ttsPoints?.geometry.dispose();
      (ttsPoints?.material as THREE.Material)?.dispose();
    };
  }, [open, analyserRef, ttsAnalyserRef, isPaused]);

  // Track when user speaks to clear old response
  useEffect(() => {
    if (recordingState === "recording") {
      setHasSpokenSinceResponse(true);
    }
  }, [recordingState]);

  // Update displayed response when new response arrives
  useEffect(() => {
    if (latestResponse && latestResponse !== lastResponseRef.current) {
      lastResponseRef.current = latestResponse;
      setDisplayedResponse(latestResponse);
      setHasSpokenSinceResponse(false);
    }
  }, [latestResponse]);

  // Handle pause/unpause
  const handlePauseToggle = () => {
    if (isPaused) {
      resumeListening();
      setIsPaused(false);
    } else {
      pauseListening();
      setIsPaused(true);
    }
  };

  const handleClose = () => {
    if (animationFrameRef.current) {
      cancelAnimationFrame(animationFrameRef.current);
    }
    setIsPaused(false);
    setDisplayedResponse("");
    setHasSpokenSinceResponse(false);
    lastResponseRef.current = "";
    stopListeningMode();
  };


  if (!open) return null;

  return (
    <div className="fixed inset-0 z-50 bg-background/30 backdrop-blur-md flex items-center justify-center">
      <div className="relative w-full h-full flex flex-col items-center justify-center">
        {/* 3D Point Cloud Visualization */}
        <div
          ref={containerRef}
          className="fixed top-1/2 left-1/2 -translate-x-1/2 -translate-y-1/2 flex items-center justify-center"
          style={{ width: "min(95vw, 800px)", height: "min(95vw, 800px)" }}
        />

        {/* LLM Response text */}
        {displayedResponse && recordingState === "listening" && !hasSpokenSinceResponse && (
          <div className="absolute top-8 left-1/2 -translate-x-1/2 max-w-3xl px-8 text-center">
            <TextAnimate
              animation="blurIn"
              by="line"
              duration={0.8}
              className="text-2xl font-medium text-foreground"
              style={{
                opacity: 0.9,
                textShadow: '0 0 20px rgba(255, 255, 255, 0.8), 0 0 40px rgba(255, 255, 255, 0.4)',
                whiteSpace: 'pre-wrap'
              }}
            >
              {displayedResponse}
            </TextAnimate>
          </div>
        )}

        {/* Control buttons */}
        <div className="absolute bottom-8 flex items-center gap-4">
          <Button
            size="icon"
            variant="secondary"
            onClick={handlePauseToggle}
            className="h-14 w-14 rounded-full bg-gray-500 hover:bg-gray-600"
          >
            {isPaused ? (
              <Play className="size-6 stroke-white" />
            ) : (
              <Pause className="size-6 stroke-white" />
            )}
          </Button>

          <Button
            size="icon"
            variant="destructive"
            onClick={handleClose}
            className="h-14 w-14 rounded-full bg-red-500 hover:bg-red-600"
          >
            <X className="size-6" />
          </Button>
        </div>
      </div>
    </div>
  );
}

import { FC, useEffect, useState, useRef, useContext } from "react";
import { Mic, Square, Loader2, Radio, AudioWaveform } from "lucide-react";
import { cn } from "@/lib/utils";
import { TooltipIconButton } from "@/components/assistant-ui/tooltip-icon-button";
import { useVoiceRecorderContext } from "@/contexts/voice-recorder-context";
import { ListeningModeContext } from "@/components/assistant-ui/thread";

interface VoiceRecorderProps {
  onTranscription: (text: string) => void;
  onAutoSend?: () => void; // Callback to trigger LLM send
  onRecordingStart?: () => void; // Callback when user starts talking
  disabled?: boolean;
  isThreadRunning?: boolean; // Whether the LLM is currently responding
  isAudioPlaying?: boolean; // Whether TTS audio is currently playing
}

export const VoiceRecorder: FC<VoiceRecorderProps> = ({
  onTranscription,
  onAutoSend,
  onRecordingStart,
  disabled = false,
  isThreadRunning = false,
  isAudioPlaying = false,
}) => {
  const {
    recordingState,
    startRecording,
    stopRecording,
    sendRecording,
    cancelRecording,
    startListeningMode,
    stopListeningMode,
    pauseListening,
    resumeListening,
    hasRecording,
  } = useVoiceRecorderContext();

  const [recordingDuration, setRecordingDuration] = useState(0);
  const sendOnStopRef = useRef(false);
  const isListeningModeActiveRef = useRef(false);
  const lastSentBlobRef = useRef<Blob | null>(null);

  // Timer for recording duration
  useEffect(() => {
    if (recordingState === "recording") {
      const interval = setInterval(() => {
        setRecordingDuration((prev) => prev + 1);
      }, 1000);

      return () => clearInterval(interval);
    } else {
      setRecordingDuration(0);
    }
  }, [recordingState]);

  const { setIsListeningMode } = useContext(ListeningModeContext);

  // Update listening mode context - keep modal open during entire listening session
  useEffect(() => {
    // If we're back to idle and were in listening mode, end the session
    if (recordingState === "idle" && isListeningModeActiveRef.current) {
      isListeningModeActiveRef.current = false;
    }
    setIsListeningMode(isListeningModeActiveRef.current);
  }, [recordingState, setIsListeningMode]);

  // Pause/resume listening based on thread running state
  // NOTE: We keep VAD active during audio playback so it can detect interruptions
  useEffect(() => {
    if (recordingState === "listening") {
      if (isThreadRunning) {
        // LLM is responding (streaming), pause VAD monitoring
        pauseListening();
      } else {
        // LLM finished, resume VAD monitoring
        // VAD will remain active even during audio playback to detect user interruptions
        resumeListening();
      }
    }
  }, [isThreadRunning, recordingState, pauseListening, resumeListening]);

  // Stop audio immediately when recording starts
  useEffect(() => {
    if (recordingState === "recording" && isAudioPlaying && onRecordingStart) {
      // Recording started while audio was playing - stop the audio immediately
      onRecordingStart();
    }
  }, [recordingState, isAudioPlaying, onRecordingStart]);

  // Also stop audio when VAD detects voice in listening mode (backup)
  useEffect(() => {
    if (recordingState === "listening" && hasRecording && isAudioPlaying && onRecordingStart) {
      // VAD detected voice while audio was playing - stop the audio immediately
      onRecordingStart();
    }
  }, [recordingState, hasRecording, isAudioPlaying, onRecordingStart]);

  // Auto-send after stopping recording
  useEffect(() => {
    const autoSend = async () => {
      // Get the current audio blob from the hook (we need to access it)
      // Since we can't access the blob directly, we'll use hasRecording as a proxy

      // Handle auto-send for normal recording (idle state)
      if (recordingState === "idle" && hasRecording && sendOnStopRef.current && !isListeningModeActiveRef.current) {
        sendOnStopRef.current = false;
        try {
          await sendRecording(onTranscription);
        } catch (error) {
          alert("Failed to transcribe audio. Please try again.");
        }
      }

      // Handle auto-send for listening mode (returns to listening state)
      if (recordingState === "listening" && hasRecording && isListeningModeActiveRef.current) {
        // Pause listening while transcribing and waiting for LLM
        pauseListening();

        try {
          await sendRecording(onTranscription);

          // Auto-send to LLM after transcription
          if (onAutoSend) {
            setTimeout(() => {
              onAutoSend();
            }, 300); // Delay to ensure text is in textarea and React state is updated
          }
        } catch (error) {
          // Resume listening even on error
          resumeListening();
        }
      }
    };

    autoSend();
  }, [recordingState, hasRecording, sendRecording, onTranscription, onAutoSend, pauseListening, resumeListening]);

  // Handle mic button click (regular recording)
  const handleMicClick = async () => {
    if (disabled) return;

    // Toggle regular recording
    if (recordingState === "idle") {
      // Start regular recording
      try {
        // Stop any playing audio when user starts recording
        if (onRecordingStart) {
          onRecordingStart();
        }
        await startRecording();
      } catch (error) {
        alert("Failed to access microphone. Please check permissions.");
      }
    } else if (recordingState === "recording") {
      // Stop recording and mark for auto-send
      sendOnStopRef.current = true;
      stopRecording();
    }
  };

  // Handle waveform button click (continuous/listening mode)
  const handleWaveformClick = async () => {
    if (disabled) return;

    // Toggle listening mode
    if (recordingState === "listening" || isListeningModeActiveRef.current) {
      isListeningModeActiveRef.current = false;
      sendOnStopRef.current = false;
      stopListeningMode();
    } else if (recordingState === "idle") {
      // Start listening mode
      isListeningModeActiveRef.current = true;
      sendOnStopRef.current = true;
      try {
        // Stop any playing audio when user starts listening mode
        if (onRecordingStart) {
          onRecordingStart();
        }
        await startListeningMode();
      } catch (error) {
        alert("Failed to access microphone. Please check permissions.");
        isListeningModeActiveRef.current = false;
      }
    }
  };

  const formatDuration = (seconds: number) => {
    const mins = Math.floor(seconds / 60);
    const secs = seconds % 60;
    return `${mins}:${secs.toString().padStart(2, "0")}`;
  };

  const isListening = recordingState === "listening";
  const isRecording = recordingState === "recording";
  const isProcessing = recordingState === "processing";

  return (
    <div className="flex items-center gap-2">
      {/* Waveform button for continuous/listening mode */}
      <TooltipIconButton
        tooltip={
          isProcessing
            ? "Transcribing..."
            : isListening
            ? "Stop continuous mode"
            : "Continuous mode"
        }
        variant={isListening ? "default" : "ghost"}
        size="icon"
        className={cn(
          "size-[34px] rounded-full transition-all duration-200",
          isListening &&
            "bg-blue-500 hover:bg-blue-600 dark:bg-blue-500 dark:hover:bg-blue-600",
          isProcessing && "opacity-50 cursor-not-allowed"
        )}
        onClick={handleWaveformClick}
        disabled={disabled || isProcessing || isRecording}
        aria-label={
          isProcessing
            ? "Transcribing..."
            : isListening
            ? "Stop continuous mode"
            : "Start continuous mode"
        }
      >
        {isListening ? (
          <Radio className="size-5" />
        ) : (
          <AudioWaveform className="size-5" />
        )}
      </TooltipIconButton>

      {/* Mic button for regular recording */}
      <TooltipIconButton
        tooltip={
          isProcessing
            ? "Transcribing..."
            : isRecording
            ? "Stop and send"
            : "Click to record"
        }
        variant={isRecording ? "default" : "ghost"}
        size="icon"
        className={cn(
          "aui-voice-recorder size-[34px] rounded-full transition-all duration-200",
          isRecording &&
            "bg-red-500 hover:bg-red-600 dark:bg-red-500 dark:hover:bg-red-600 animate-pulse",
          isProcessing && "opacity-50 cursor-not-allowed"
        )}
        onClick={handleMicClick}
        disabled={disabled || isProcessing || isListening}
        aria-label={
          isProcessing
            ? "Transcribing..."
            : isRecording
            ? "Stop and send"
            : "Click to record"
        }
      >
        {isProcessing ? (
          <Loader2 className="size-5 animate-spin" />
        ) : isRecording ? (
          <Square className="size-4 fill-white dark:fill-black" />
        ) : (
          <Mic className="size-5" />
        )}
      </TooltipIconButton>
    </div>
  );
};

"use client";

import { Component, type FC, type ReactNode } from "react";
import { cn } from "@/lib/utils";
import { findBlock, hiddenBlocks, type BlockContext } from "./registry";

/**
 * Models write almost-JSON. Repair the usual slips before giving up:
 * trailing commas and raw line breaks inside strings.
 */
export const sanitizeJSON = (jsonString: string): string => {
  return jsonString
    // Remove trailing commas before closing braces/brackets
    .replace(/,(\s*[}\]])/g, "$1")
    // Escape literal newlines that sit inside a quoted string
    .split("\n")
    .map((line, i, arr) => {
      if (i === 0) return line;
      const prevLines = arr.slice(0, i).join("\n");
      const quoteCount = (prevLines.match(/(?<!\\)"/g) || []).length;
      return quoteCount % 2 !== 0 ? "\\n" + line : line;
    })
    .join("");
};

export type ParsedBlock =
  | { ok: true; data: any }
  | { ok: false; error: string };

export const parseBlock = (code: string): ParsedBlock => {
  try {
    return { ok: true, data: JSON.parse(code) };
  } catch (firstError) {
    try {
      return { ok: true, data: JSON.parse(sanitizeJSON(code)) };
    } catch {
      return { ok: false, error: (firstError as Error).message };
    }
  }
};

/** A block that throws must not take the whole message down with it. */
class BlockBoundary extends Component<
  { children: ReactNode; fallback: ReactNode; resetKey: string },
  { failed: boolean }
> {
  state = { failed: false };

  static getDerivedStateFromError() {
    return { failed: true };
  }

  componentDidUpdate(prev: { resetKey: string }) {
    if (prev.resetKey !== this.props.resetKey && this.state.failed) {
      this.setState({ failed: false });
    }
  }

  render() {
    return this.state.failed ? this.props.fallback : this.props.children;
  }
}

export const BlockSkeleton: FC<{ className?: string }> = ({ className }) => (
  <div
    className={cn(
      "h-28 w-full max-w-2xl animate-pulse rounded-2xl border bg-muted/60",
      className,
    )}
    aria-hidden
  />
);

export interface BlockRendererProps extends Partial<BlockContext> {
  /** The fence language: `plan`, `chart`, ... */
  type: string;
  /** The raw text inside the fence. */
  code: string;
  /** Shown while the JSON is incomplete (streaming) or invalid. Defaults to nothing. */
  fallback?: ReactNode;
  className?: string;
}

const noop = () => {};

/**
 * Turns one fenced block into its component.
 * Pure: no chat runtime, no network. Give it `send` to make interactive blocks talk back.
 */
export const BlockRenderer: FC<BlockRendererProps> = ({
  type,
  code,
  send = noop,
  isLatest = true,
  fallback = null,
  className,
}) => {
  if (hiddenBlocks.includes(type)) return null;

  const block = findBlock(type);
  if (!block) return null;

  const parsed = parseBlock(code);
  if (!parsed.ok) return <>{fallback}</>;

  return (
    <BlockBoundary fallback={fallback} resetKey={code}>
      <div className={cn("not-prose my-4", className)} data-block={block.name}>
        {block.render(parsed.data, { send, isLatest })}
      </div>
    </BlockBoundary>
  );
};

"use client";

import { FC } from "react";
import { Bar, BarChart, CartesianGrid, Legend, Line, LineChart, XAxis, YAxis } from "recharts";
import { ChartContainer, ChartTooltip, ChartTooltipContent, ChartConfig } from "@/components/ui/chart";
import type { SerializableChart } from "./schema";
import { cn } from "@/lib/utils";

interface ChartProps extends SerializableChart {
  className?: string;
  onDataPointClick?: (dataPoint: any) => void;
}

export const Chart: FC<ChartProps> = ({
  id,
  type,
  title,
  description,
  data,
  xKey,
  series,
  showLegend = true,
  showGrid = true,
  className,
  onDataPointClick,
}) => {
  // Build ChartConfig from series
  const chartConfig: ChartConfig = series.reduce((config, s) => {
    config[s.key] = {
      label: s.label,
      color: s.color,
    };
    return config;
  }, {} as ChartConfig);

  // Default colors for series without explicit colors
  const defaultColors = [
    "hsl(var(--chart-1))",
    "hsl(var(--chart-2))",
    "hsl(var(--chart-3))",
    "hsl(var(--chart-4))",
    "hsl(var(--chart-5))",
  ];

  return (
    <div
      className={cn("flex flex-col gap-2", className)}
      data-tool-ui-id={id}
      data-slot="chart"
    >
      {(title || description) && (
        <div className="space-y-1">
          {title && <h3 className="text-lg font-semibold">{title}</h3>}
          {description && <p className="text-sm text-muted-foreground">{description}</p>}
        </div>
      )}

      <ChartContainer id={id} config={chartConfig}>
        {type === "bar" ? (
          <BarChart data={data} onClick={onDataPointClick}>
            {showGrid && <CartesianGrid strokeDasharray="3 3" vertical={false} />}
            <XAxis
              dataKey={xKey}
              tickLine={false}
              tickMargin={10}
              axisLine={false}
            />
            <YAxis
              tickLine={false}
              axisLine={false}
              tickFormatter={(value) => {
                if (value >= 1000000) return `${(value / 1000000).toFixed(1)}M`;
                if (value >= 1000) return `${(value / 1000).toFixed(1)}K`;
                return value.toString();
              }}
            />
            <ChartTooltip content={<ChartTooltipContent />} />
            {showLegend && <Legend />}
            {series.map((s, index) => (
              <Bar
                key={s.key}
                dataKey={s.key}
                fill={s.color || defaultColors[index % defaultColors.length]}
                radius={[4, 4, 0, 0]}
              />
            ))}
          </BarChart>
        ) : (
          <LineChart data={data} onClick={onDataPointClick}>
            {showGrid && <CartesianGrid strokeDasharray="3 3" vertical={false} />}
            <XAxis
              dataKey={xKey}
              tickLine={false}
              tickMargin={10}
              axisLine={false}
            />
            <YAxis
              tickLine={false}
              axisLine={false}
              tickFormatter={(value) => {
                if (value >= 1000000) return `${(value / 1000000).toFixed(1)}M`;
                if (value >= 1000) return `${(value / 1000).toFixed(1)}K`;
                return value.toString();
              }}
            />
            <ChartTooltip content={<ChartTooltipContent />} />
            {showLegend && <Legend />}
            {series.map((s, index) => (
              <Line
                key={s.key}
                type="monotone"
                dataKey={s.key}
                stroke={s.color || defaultColors[index % defaultColors.length]}
                strokeWidth={2}
                dot={{ r: 3 }}
                activeDot={{ r: 5 }}
              />
            ))}
          </LineChart>
        )}
      </ChartContainer>
    </div>
  );
};

export { Chart } from "./chart";
export { parseSerializableChart } from "./schema";
export type { SerializableChart, ChartSeries } from "./schema";

export interface ChartSeries {
  key: string;
  label: string;
  color?: string;
}

export interface SerializableChart {
  id: string;
  type: "bar" | "line";
  title?: string;
  description?: string;
  data: Record<string, any>[];
  xKey: string;
  series: ChartSeries[];
  showLegend?: boolean;
  showGrid?: boolean;
}

export function parseSerializableChart(data: any): SerializableChart {
  // Check if data is in the dataSeries format with x/y objects
  if (data.dataSeries?.[0]?.data?.[0]?.x !== undefined) {
    // Transform dataSeries[].data[{x,y}] format to expected format
    const firstSeries = data.dataSeries[0];
    const xValues = firstSeries.data.map((point: any) => point.x);
    const transformedData: Record<string, any>[] = xValues.map((xVal: any, index: number) => {
      const row: Record<string, any> = { x: xVal };
      data.dataSeries.forEach((s: any, seriesIndex: number) => {
        const key = `series${seriesIndex}`;
        row[key] = s.data?.[index]?.y;
      });
      return row;
    });

    const transformedSeries: ChartSeries[] = data.dataSeries.map((s: any, index: number) => ({
      key: `series${index}`,
      label: s.name || s.label || `Series ${index + 1}`,
      color: s.color,
    }));

    return {
      id: data.id || crypto.randomUUID(),
      type: data.type || "bar",
      title: data.title,
      description: data.description,
      data: transformedData,
      xKey: "x",
      series: transformedSeries,
      showLegend: data.showLegend ?? true,
      showGrid: data.showGrid ?? true,
    };
  }

  // Check if data is in the alternative format with xAxis.categories and series[].data
  if (data.xAxis?.categories && data.series?.[0]?.data) {
    // Transform xAxis.categories + series[].data format to expected format
    const xValues = data.xAxis.categories || [];
    const transformedData: Record<string, any>[] = xValues.map((xVal: any, index: number) => {
      const row: Record<string, any> = { x: xVal };
      data.series.forEach((s: any, seriesIndex: number) => {
        const key = `series${seriesIndex}`;
        row[key] = s.data?.[index];
      });
      return row;
    });

    const transformedSeries: ChartSeries[] = data.series.map((s: any, index: number) => ({
      key: `series${index}`,
      label: s.name || s.label || `Series ${index + 1}`,
      color: s.color,
    }));

    return {
      id: data.id || crypto.randomUUID(),
      type: data.type || "bar",
      title: data.title,
      description: data.description,
      data: transformedData,
      xKey: "x",
      series: transformedSeries,
      showLegend: data.showLegend ?? true,
      showGrid: data.showGrid ?? true,
    };
  }

  // Check if data is in the alternative format with xAxis.values and series[].values (camelCase)
  if (data.xAxis?.values && data.series?.[0]?.values) {
    // Transform xAxis.values + series[].values format to expected format
    const xValues = data.xAxis.values || [];
    const transformedData: Record<string, any>[] = xValues.map((xVal: any, index: number) => {
      const row: Record<string, any> = { x: xVal };
      data.series.forEach((s: any, seriesIndex: number) => {
        const key = `series${seriesIndex}`;
        row[key] = s.values?.[index];
      });
      return row;
    });

    const transformedSeries: ChartSeries[] = data.series.map((s: any, index: number) => ({
      key: `series${index}`,
      label: s.name || s.label || `Series ${index + 1}`,
      color: s.color,
    }));

    return {
      id: data.id || crypto.randomUUID(),
      type: data.type || "bar",
      title: data.title,
      description: data.description,
      data: transformedData,
      xKey: "x",
      series: transformedSeries,
      showLegend: data.showLegend ?? true,
      showGrid: data.showGrid ?? true,
    };
  }

  // Check if data is in the alternative format with x_axis/y_axis/series.values (snake_case)
  if (data.x_axis && data.series?.[0]?.values) {
    // Transform alternative format to expected format
    const xValues = data.x_axis.values || [];
    const transformedData: Record<string, any>[] = xValues.map((xVal: any, index: number) => {
      const row: Record<string, any> = { x: xVal };
      data.series.forEach((s: any, seriesIndex: number) => {
        const key = `series${seriesIndex}`;
        row[key] = s.values?.[index];
      });
      return row;
    });

    const transformedSeries: ChartSeries[] = data.series.map((s: any, index: number) => ({
      key: `series${index}`,
      label: s.name || s.label || `Series ${index + 1}`,
      color: s.color,
    }));

    return {
      id: data.id || crypto.randomUUID(),
      type: data.type || "bar",
      title: data.title,
      description: data.description,
      data: transformedData,
      xKey: "x",
      series: transformedSeries,
      showLegend: data.showLegend ?? true,
      showGrid: data.showGrid ?? true,
    };
  }

  // Check if data is in the series[].data[{x, y}] format (similar to dataSeries but uses 'series')
  if (data.series?.[0]?.data?.[0]?.x !== undefined) {
    // Transform series[].data[{x,y}] format to expected format
    const firstSeries = data.series[0];
    const xValues = firstSeries.data.map((point: any) => point.x);
    const transformedData: Record<string, any>[] = xValues.map((xVal: any, index: number) => {
      const row: Record<string, any> = { x: xVal };
      data.series.forEach((s: any, seriesIndex: number) => {
        const key = `series${seriesIndex}`;
        row[key] = s.data?.[index]?.y;
      });
      return row;
    });

    const transformedSeries: ChartSeries[] = data.series.map((s: any, index: number) => ({
      key: `series${index}`,
      label: s.name || s.label || `Series ${index + 1}`,
      color: s.color,
    }));

    return {
      id: data.id || crypto.randomUUID(),
      type: data.type || data.series?.[0]?.type || "bar",
      title: data.title || data.xAxisTitle,
      description: data.description || data.yAxisTitle,
      data: transformedData,
      xKey: "x",
      series: transformedSeries,
      showLegend: data.showLegend ?? true,
      showGrid: data.showGrid ?? true,
    };
  }

  // Standard format
  return {
    id: data.id || crypto.randomUUID(),
    type: data.type || "bar",
    title: data.title,
    description: data.description,
    data: data.data || [],
    xKey: data.xKey || "x",
    series: data.series || [],
    showLegend: data.showLegend ?? true,
    showGrid: data.showGrid ?? true,
  };
}

