interface ItemCardProps {
  item: Item;
  onItemClick?: (itemId: string, itemName: string) => void;
  onActionClick?: (prompt: string) => void;
}

const ItemCard: FC<ItemCardProps> = ({ item, onItemClick, onActionClick }) => {
  const handleCardClick = () => {
    if (onItemClick) {
      onItemClick(item.id, item.name);
    }
  };

  const handleActionClick = (prompt: string, e: React.MouseEvent) => {
    e.stopPropagation();
    if (onActionClick) {
      onActionClick(prompt);
    }
  };

  const handleKeyDown = (e: React.KeyboardEvent) => {
    if (e.key === "Enter" || e.key === " ") {
      e.preventDefault();
      handleCardClick();
    }
  };

  return (
    <div
      data-carousel-item="true"
      data-item-id={item.id}
      role="listitem"
      className="flex snap-start snap-always"
    >
      <div
        data-slot="card"
        className={cn(
          "bg-card text-card-foreground border shadow-none",
          "group @container/card relative flex w-44 flex-col gap-0 self-stretch overflow-clip rounded-md p-0",
          "@lg:w-56",
          onItemClick && "cursor-pointer hover:shadow focus-visible:ring-ring focus-visible:ring-offset-background focus-visible:ring-2 focus-visible:ring-offset-2 focus-visible:outline-none touch-manipulation"
        )}
        role={onItemClick ? "button" : undefined}
        tabIndex={onItemClick ? 0 : undefined}
        aria-label={onItemClick ? `View item: ${item.name}` : undefined}
        onClick={onItemClick ? handleCardClick : undefined}
        onKeyDown={onItemClick ? handleKeyDown : undefined}
      >
        {/* Image or Color Block */}
        <div className="bg-muted relative aspect-square w-full overflow-hidden">
          {item.imageUrl ? (
            <img
              src={item.imageUrl}
              alt={item.name}
              className="h-full w-full object-cover transition-transform duration-300 group-hover:scale-105"
              loading="lazy"
            />
          ) : (
            <div
              className="h-full w-full transition-transform duration-300 group-hover:scale-105"
              role="img"
              aria-label={item.name}
              style={{ backgroundColor: item.color || "#6366f1" }}
            />
          )}
        </div>

        {/* Content */}
        <div className="flex flex-1 flex-col gap-1 p-3">
          <div className="flex flex-col gap-1">
            <h3 className="line-clamp-2 text-sm leading-tight font-medium">
              {item.name}
            </h3>
            {item.subtitle && (
              <p className="text-muted-foreground line-clamp-1 text-sm">
                {item.subtitle}
              </p>
            )}
          </div>

          {/* Actions */}
          {item.actions && item.actions.length > 0 && (
            <div className="mt-auto flex flex-col-reverse gap-2 pt-2 @[176px]/card:flex-row">
              {item.actions.map((action) => (
                <Button
                  key={action.id}
                  variant={action.variant || "default"}
                  size="sm"
                  disabled={action.disabled}
                  onClick={(e) => handleActionClick(action.prompt || action.label, e)}
                  className={cn(
                    "min-h-11 w-full px-3",
                    "md:min-h-8",
                    "@[176px]/card:h-8 @[176px]/card:w-auto @[176px]/card:flex-1"
                  )}
                >
                  {action.label}
                </Button>
              ))}
            </div>
          )}
        </div>
      </div>
    </div>
  );
};

import type { Action } from "../shared/schema";

export interface CarouselItem {
  id: string;
  name: string;
  subtitle?: string;
  description?: string;
  imageUrl?: string;
  color?: string;
  actions?: Action[];
}

export interface SerializableItemCarousel {
  id: string;
  items: CarouselItem[];
  loop?: boolean;
  autoPlay?: boolean;
  autoPlayInterval?: number;
}

export function parseSerializableItemCarousel(data: any): SerializableItemCarousel {
  // Auto-generate IDs for items if not provided
  const items = (data.items || []).map((item: any) => ({
    ...item,
    id: item.id || crypto.randomUUID(),
  }));

  return {
    id: data.id || crypto.randomUUID(),
    items,
    loop: data.loop ?? true,
    autoPlay: data.autoPlay ?? false,
    autoPlayInterval: data.autoPlayInterval ?? 1000,
  };
}

