"use client";

import { motion, useInView, Variant } from "motion/react";
import { useRef, useMemo, type ElementType } from "react";
import { cn } from "@/lib/utils";

type AnimationType = "blurIn" | "blurInUp" | "fadeIn" | "slideUp";
type AnimationBy = "character" | "word" | "line" | "text";

interface TextAnimateProps {
  children: string;
  animation?: AnimationType;
  by?: AnimationBy;
  as?: ElementType;
  className?: string;
  delay?: number;
  duration?: number;
  once?: boolean;
  style?: React.CSSProperties;
}

const animationVariants: Record<
  AnimationType,
  { hidden: Variant; visible: Variant }
> = {
  blurIn: {
    hidden: { opacity: 0, filter: "blur(10px)" },
    visible: { opacity: 1, filter: "blur(0px)" },
  },
  blurInUp: {
    hidden: { opacity: 0, filter: "blur(10px)", y: 20 },
    visible: { opacity: 1, filter: "blur(0px)", y: 0 },
  },
  fadeIn: {
    hidden: { opacity: 0 },
    visible: { opacity: 1 },
  },
  slideUp: {
    hidden: { opacity: 0, y: 20 },
    visible: { opacity: 1, y: 0 },
  },
};

export function TextAnimate({
  children,
  animation = "blurIn",
  by = "word",
  as: Component = "p",
  className,
  delay = 0,
  duration = 0.5,
  once = true,
  style,
}: TextAnimateProps) {
  const ref = useRef(null);
  const isInView = useInView(ref, { once, amount: 0.1 });

  const segments = useMemo(() => {
    if (by === "text") return [children];
    if (by === "line") return children.split("\n");
    if (by === "word") return children.split(" ");
    if (by === "character") return children.split("");
    return [children];
  }, [children, by]);

  const variants = animationVariants[animation];

  const containerVariants = {
    hidden: {},
    visible: {
      transition: {
        staggerChildren: by === "text" ? 0 : by === "line" ? 0.3 : by === "word" ? 0.1 : 0.03,
        delayChildren: delay,
      },
    },
  };

  if (by === "text") {
    return (
      <motion.div
        ref={ref}
        initial="hidden"
        animate={isInView ? "visible" : "hidden"}
        variants={containerVariants}
      >
        <motion.div
          variants={variants}
          transition={{ duration }}
          className={cn(className)}
        >
          {Component === "p" || Component === "span" || Component === "div" ? (
            <Component className={cn(className)}>{children}</Component>
          ) : (
            children
          )}
        </motion.div>
      </motion.div>
    );
  }

  return (
    <Component ref={ref} className={cn(className)} style={style}>
      <motion.span
        initial="hidden"
        animate={isInView ? "visible" : "hidden"}
        variants={containerVariants}
        style={{ display: "inline-block" }}
      >
        {segments.map((segment, i) => (
          <motion.span
            key={`${segment}-${i}`}
            variants={variants}
            transition={{ duration }}
            style={{ display: "inline-block" }}
          >
            {segment}
            {by === "word" && i < segments.length - 1 && "\u00A0"}
            {by === "line" && i < segments.length - 1 && <br />}
          </motion.span>
        ))}
      </motion.span>
    </Component>
  );
}

"use client";

import { useState } from "react";
import { WorkflowState, NodeStatus } from "@/lib/types";
import { CheckCircle2, Circle, Loader2, XCircle, Clock, CircleDotDashed, AlertCircle } from "lucide-react";
import { cn } from "@/lib/utils";
import {
  Popover,
  PopoverContent,
  PopoverTrigger,
} from "@/components/ui/popover";

interface WorkflowStatusProps {
  workflowState: WorkflowState;
}

export function WorkflowStatus({ workflowState }: WorkflowStatusProps) {
  const [isOpen, setIsOpen] = useState(false);

  if (workflowState.status === "idle" || !workflowState.workflowRunId) {
    return null;
  }

  // Determine effective status - check for partial success
  const getEffectiveStatus = () => {
    if (workflowState.status === "running") return "running";
    if (workflowState.status === "canceled") return "canceled";

    // Check if we have mixed results (some completed, some failed)
    const hasCompleted = workflowState.nodes.some(n => n.status === "completed");
    const hasFailed = workflowState.nodes.some(n => n.status === "failed" || n.status === "cancelled");

    if (hasCompleted && hasFailed) {
      // Check if the last node failed
      const lastNode = workflowState.nodes[workflowState.nodes.length - 1];
      if (lastNode && (lastNode.status === "failed" || lastNode.status === "cancelled")) {
        return "failed";
      }
      // Mixed results but last didn't fail = partial success
      return "partial";
    }

    return workflowState.status;
  };

  const effectiveStatus = getEffectiveStatus();

  const getStatusIcon = (status: NodeStatus | string, size: "sm" | "md" = "md") => {
    const sizeClass = size === "sm" ? "h-3 w-3" : "h-4 w-4";

    switch (status) {
      case "pending":
        return <Circle className={cn(sizeClass, "text-muted-foreground")} />;
      case "in_progress":
        return <Loader2 className={cn(sizeClass, "animate-spin text-blue-500")} />;
      case "completed":
        return <CheckCircle2 className={cn(sizeClass, "text-emerald-500")} />;
      case "failed":
        return <XCircle className={cn(sizeClass, "text-red-500")} />;
      case "cancelled":
      case "canceled":
        return <XCircle className={cn(sizeClass, "text-orange-500")} />;
      case "running":
        return <Loader2 className={cn(sizeClass, "animate-spin text-blue-500")} />;
      case "succeeded":
        return <CheckCircle2 className={cn(sizeClass, "text-emerald-500")} />;
      case "stopped":
        return <Circle className={cn(sizeClass, "text-gray-400")} />;
      case "partial":
        return <AlertCircle className={cn(sizeClass, "text-yellow-500")} />;
      default:
        return <Circle className={cn(sizeClass, "text-gray-300")} />;
    }
  };

  const getNodeTextStyle = (status: NodeStatus) => {
    switch (status) {
      case "pending":
        return "text-muted-foreground";
      case "in_progress":
        return "text-foreground";
      case "completed":
        return "text-emerald-600 dark:text-emerald-400";
      case "failed":
      case "cancelled":
        return "text-destructive line-through";
      default:
        return "text-foreground";
    }
  };

  const formatTime = (seconds: number) => {
    return `${seconds.toFixed(1)}s`;
  };

  const isRunning = effectiveStatus === "running";
  const progressPercent = workflowState.totalSteps > 0
    ? (workflowState.completedSteps / workflowState.totalSteps) * 100
    : 0;

  const getStatusLabel = () => {
    if (isRunning && workflowState.currentNode) {
      return workflowState.currentNode.title;
    }
    if (effectiveStatus === "succeeded") return "Completed";
    if (effectiveStatus === "partial") return "Partial Success";
    if (effectiveStatus === "failed") return "Failed";
    if (effectiveStatus === "stopped") return "Stopped";
    if (effectiveStatus === "canceled") return "Partially Canceled by user";
    return "Processing";
  };

  const getStatusColor = () => {
    if (isRunning) return "text-primary/50";
    if (effectiveStatus === "succeeded") return "text-emerald-600 dark:text-emerald-400";
    if (effectiveStatus === "partial") return "text-yellow-600 dark:text-yellow-400";
    if (effectiveStatus === "failed") return "text-red-600 dark:text-red-400";
    if (effectiveStatus === "canceled") return "text-orange-600 dark:text-orange-400";
    return "text-muted-foreground";
  };

  return (
    <Popover open={isOpen} onOpenChange={setIsOpen}>
      <PopoverTrigger asChild>
        <button
          className={cn(
            "inline-flex items-center gap-1.5 cursor-pointer transition-colors",
            "hover:bg-accent/50 rounded-md px-2 py-1.5 -mx-2",
            "text-xs"
          )}
        >
          {/* Rotating icon when running */}
          {isRunning ? (
            <span className="inline-flex shrink-0 motion-safe:animate-[plan-spin_8s_linear_infinite]">
              <CircleDotDashed className="h-4 w-4 shrink-0 text-muted-foreground" aria-hidden="true" />
            </span>
          ) : (
            getStatusIcon(effectiveStatus, "sm")
          )}

          <span className={cn(
            "font-medium",
            isRunning ? "motion-safe:shimmer text-primary/50" : getStatusColor()
          )}>
            {getStatusLabel()}
          </span>

          {workflowState.totalSteps > 0 && (
            <span className="text-[10px] text-muted-foreground">
              {workflowState.completedSteps}/{workflowState.totalSteps}
            </span>
          )}
          {workflowState.elapsedTime > 0 && !isRunning && (
            <span className="text-[10px] text-muted-foreground flex items-center gap-0.5">
              <Clock className="h-2.5 w-2.5" />
              {formatTime(workflowState.elapsedTime)}
            </span>
          )}
        </button>
      </PopoverTrigger>

      <PopoverContent
        className="w-[380px] p-3"
        align="start"
        side="top"
      >
        <div className="space-y-3">
          {/* Header */}
          <div className="flex items-center justify-between">
            <div className="flex items-center gap-2">
              {getStatusIcon(effectiveStatus)}
              <h4 className="font-semibold text-sm">Workflow Execution</h4>
            </div>
            {workflowState.elapsedTime > 0 && (
              <div className="flex items-center gap-1 text-xs text-muted-foreground">
                <Clock className="h-3 w-3" />
                {formatTime(workflowState.elapsedTime)}
              </div>
            )}
          </div>

          {/* Progress Bar */}
          {workflowState.totalSteps > 0 && (
            <div>
              <div className="mb-1.5 flex items-center justify-between text-xs text-muted-foreground">
                <span>Progress</span>
                <span>
                  {workflowState.completedSteps} / {workflowState.totalSteps} steps
                </span>
              </div>
              <div className="h-1.5 w-full overflow-hidden rounded-full bg-muted">
                <div
                  className={cn(
                    "h-full transition-all duration-300",
                    isRunning ? "bg-blue-500" : "bg-emerald-500"
                  )}
                  style={{ width: `${progressPercent}%` }}
                />
              </div>
            </div>
          )}

          {/* Execution Steps */}
          {workflowState.nodes.length > 0 && (
            <div className="space-y-1.5 pt-1">
              <h5 className="text-xs font-medium text-muted-foreground">Steps</h5>
              <ul className="space-y-0 max-h-[400px] overflow-y-auto">
                {workflowState.nodes.map((node) => {
                  const hasError = node.status === "failed" || node.error;
                  const isRunning = node.status === "in_progress";

                  return (
                    <li key={node.id} className={cn("-mx-2 flex flex-col gap-2 rounded-md px-2 py-1", hasError && "bg-red-50 dark:bg-red-950/20")}>
                      {/* Node header */}
                      <div className="flex items-start gap-2">
                        <span className={cn("mt-0.5 inline-flex shrink-0", isRunning && "motion-safe:animate-[plan-spin_8s_linear_infinite]")}>
                          {getStatusIcon(node.status, "sm")}
                        </span>
                        <div className="flex-1 min-w-0">
                          <div className="flex items-center gap-2">
                            <span className={cn("text-xs", isRunning ? "motion-safe:shimmer text-primary/50" : getNodeTextStyle(node.status))}>
                              {node.title}
                            </span>

                          </div>

                          {/* Error message */}
                          {hasError && node.error && (
                            <p className="text-red-600 dark:text-red-400 text-xs mt-1">
                              {node.error}
                            </p>
                          )}

                          {/* Token usage inline */}
                          {(node.executionMetadata?.total_tokens || node.processData?.usage) && (
                            <div className="flex items-center gap-3 mt-1 text-[10px] text-muted-foreground">
                              {node.processData?.usage?.prompt_tokens && node.processData?.usage?.completion_tokens && (
                                <span className="font-mono">
                                  {node.processData.usage.prompt_tokens + node.processData.usage.completion_tokens} tokens
                                </span>
                              )}
                              {node.executionMetadata?.total_price && (
                                <span className="font-mono">
                                  ${node.executionMetadata.total_price}
                                </span>
                              )}
                              {node.processData?.usage?.latency && (
                                <span className="font-mono">
                                  {node.processData.usage.latency.toFixed(2)}s
                                </span>
                              )}
                            </div>
                          )}
                        </div>
                        {node.elapsedTime && (
                          <span className="shrink-0 text-muted-foreground text-xs tabular-nums">
                            {formatTime(node.elapsedTime)}
                          </span>
                        )}
                      </div>
                    </li>
                  );
                })}
              </ul>
            </div>
          )}

          {/* Status Message */}
          {!isRunning && (
            <div className="pt-2 border-t">
              <p className="text-xs text-muted-foreground">
                {effectiveStatus === "succeeded" && "✓ Workflow completed successfully"}
                {effectiveStatus === "partial" && "⚠ Workflow completed with some failures"}
                {effectiveStatus === "failed" && "✗ Workflow execution failed"}
                {effectiveStatus === "stopped" && "Workflow execution stopped"}
                {effectiveStatus === "canceled" && "⊘ Workflow execution canceled by user"}
              </p>
            </div>
          )}
        </div>
      </PopoverContent>
    </Popover>
  );
}

"use client";

import { createContext, useContext, type ReactNode, type RefObject } from "react";
import { useVoiceRecorder, type RecordingState } from "@/hooks/use-voice-recorder";
import { useChatKit } from "@/lib/chat-kit";

interface VoiceRecorderContextType {
  recordingState: RecordingState;
  startRecording: () => Promise<void>;
  stopRecording: () => void;
  sendRecording: (onTranscription: (text: string) => void) => Promise<void>;
  cancelRecording: () => void;
  startListeningMode: () => Promise<void>;
  stopListeningMode: () => void;
  pauseListening: () => void;
  resumeListening: () => void;
  hasRecording: boolean;
  audioContextRef: RefObject<AudioContext | null>;
  analyserRef: RefObject<AnalyserNode | null>;
}

const VoiceRecorderContext = createContext<VoiceRecorderContextType | null>(null);

export function VoiceRecorderProvider({
  children,
  onVoiceDetected,
}: {
  children: ReactNode;
  onVoiceDetected?: () => void;
}) {
  const { transcribe } = useChatKit();
  const recorder = useVoiceRecorder(onVoiceDetected, transcribe);

  return (
    <VoiceRecorderContext.Provider value={recorder}>
      {children}
    </VoiceRecorderContext.Provider>
  );
}

export function useVoiceRecorderContext() {
  const context = useContext(VoiceRecorderContext);
  if (!context) {
    throw new Error("useVoiceRecorderContext must be used within VoiceRecorderProvider");
  }
  return context;
}

import { useState, useRef, useCallback, useEffect } from "react";

export type RecordingState = "idle" | "listening" | "recording" | "processing";

export type Transcribe = (audio: File) => Promise<string>;

export function useVoiceRecorder(onVoiceDetected?: () => void, transcribe?: Transcribe) {
  const transcribeRef = useRef(transcribe);
  transcribeRef.current = transcribe;
  const [recordingState, setRecordingState] = useState<RecordingState>("idle");
  const [audioBlob, setAudioBlob] = useState<Blob | null>(null);
  const mediaRecorderRef = useRef<MediaRecorder | null>(null);
  const chunksRef = useRef<Blob[]>([]);

  // VAD (Voice Activity Detection) refs
  const audioContextRef = useRef<AudioContext | null>(null);
  const analyserRef = useRef<AnalyserNode | null>(null);
  const streamRef = useRef<MediaStream | null>(null);
  const silenceTimeoutRef = useRef<NodeJS.Timeout | null>(null);
  const vadIntervalRef = useRef<NodeJS.Timeout | null>(null);
  const isRecordingFromVADRef = useRef(false);
  const isListeningActiveRef = useRef(false);
  const silenceScheduledRef = useRef(false);
  const isListeningPausedRef = useRef(false);

  const startRecording = useCallback(async () => {
    try {
      const stream = await navigator.mediaDevices.getUserMedia({ audio: true });

      // Try formats most speech-to-text services accept, in order
      let mimeType = "audio/mp4";
      let fileExtension = "m4a";

      if (MediaRecorder.isTypeSupported("audio/mp4")) {
        mimeType = "audio/mp4";
        fileExtension = "m4a";
      } else if (MediaRecorder.isTypeSupported("audio/webm;codecs=opus")) {
        // Try webm with opus codec as fallback
        mimeType = "audio/webm;codecs=opus";
        fileExtension = "webm";
      } else if (MediaRecorder.isTypeSupported("audio/webm")) {
        mimeType = "audio/webm";
        fileExtension = "webm";
      } else {
        // Last resort - let browser decide
        mimeType = "";
        fileExtension = "webm";
      }

      const mediaRecorder = new MediaRecorder(stream, mimeType ? { mimeType } : undefined);

      chunksRef.current = [];

      mediaRecorder.ondataavailable = (event) => {
        if (event.data.size > 0) {
          chunksRef.current.push(event.data);
        }
      };

      mediaRecorder.onstop = () => {
        const actualMimeType = mimeType || mediaRecorder.mimeType;
        const blob = new Blob(chunksRef.current, { type: actualMimeType });
        setAudioBlob(blob);

        // Store the file extension for later use
        (blob as any).__fileExtension = fileExtension;

        // Stop all tracks to release the microphone
        stream.getTracks().forEach((track) => track.stop());
      };

      mediaRecorder.start();
      mediaRecorderRef.current = mediaRecorder;
      setRecordingState("recording");
    } catch (error) {
      throw error;
    }
  }, []);

  const stopRecording = useCallback(() => {
    if (mediaRecorderRef.current && recordingState === "recording") {
      mediaRecorderRef.current.stop();
      setRecordingState("idle");
    }
  }, [recordingState]);

  const sendRecording = useCallback(
    async (onTranscription: (text: string) => void) => {
      if (!audioBlob) {
        return;
      }

      setRecordingState("processing");

      try {
        if (!transcribeRef.current) {
          throw new Error("No transcribe adapter configured");
        }

        const extension = (audioBlob as any).__fileExtension || "m4a";
        const file = new File([audioBlob], `recording.${extension}`, {
          type: audioBlob.type,
        });

        const text = await transcribeRef.current(file);

        if (text) {
          onTranscription(text);
        }

        setAudioBlob(null);

        // Return to listening mode if still active, otherwise go to idle
        if (isListeningActiveRef.current) {
          setRecordingState("listening");
        } else {
          setRecordingState("idle");
        }
      } catch (error) {
        // Return to listening mode if still active, otherwise go to idle
        if (isListeningActiveRef.current) {
          setRecordingState("listening");
        } else {
          setRecordingState("idle");
        }
        throw error;
      }
    },
    [audioBlob]
  );

  const cancelRecording = useCallback(() => {
    if (mediaRecorderRef.current) {
      mediaRecorderRef.current.stop();
    }
    setAudioBlob(null);
    setRecordingState("idle");
  }, []);

  // VAD: Detect audio level
  const getAudioLevel = useCallback(() => {
    if (!analyserRef.current) return 0;

    const dataArray = new Uint8Array(analyserRef.current.frequencyBinCount);
    analyserRef.current.getByteFrequencyData(dataArray);

    // Calculate average volume
    const average = dataArray.reduce((acc, val) => acc + val, 0) / dataArray.length;
    return average;
  }, []);

  // Helper: Start recording with existing stream
  const startRecordingWithStream = useCallback(async (stream: MediaStream) => {
    try {
      // Try different formats most speech-to-text services accept, in order
      let mimeType = "audio/mp4";
      let fileExtension = "m4a";

      if (MediaRecorder.isTypeSupported("audio/mp4")) {
        mimeType = "audio/mp4";
        fileExtension = "m4a";
      } else if (MediaRecorder.isTypeSupported("audio/webm;codecs=opus")) {
        mimeType = "audio/webm;codecs=opus";
        fileExtension = "webm";
      } else if (MediaRecorder.isTypeSupported("audio/webm")) {
        mimeType = "audio/webm";
        fileExtension = "webm";
      } else {
        mimeType = "";
        fileExtension = "webm";
      }

      const mediaRecorder = new MediaRecorder(stream, mimeType ? { mimeType } : undefined);

      chunksRef.current = [];

      mediaRecorder.ondataavailable = (event) => {
        if (event.data.size > 0) {
          chunksRef.current.push(event.data);
        }
      };

      mediaRecorder.onstop = () => {
        const actualMimeType = mimeType || mediaRecorder.mimeType;
        const blob = new Blob(chunksRef.current, { type: actualMimeType });
        setAudioBlob(blob);

        // Store the file extension for later use
        (blob as any).__fileExtension = fileExtension;

        // If still in listening mode, return to listening state
        // Don't stop the stream - we're in listening mode
        if (isListeningActiveRef.current) {
          setRecordingState("listening");
        } else {
          // Not in listening mode anymore, go to idle
          setRecordingState("idle");
        }
      };

      mediaRecorder.start();
      mediaRecorderRef.current = mediaRecorder;
      setRecordingState("recording");
    } catch (error) {
      throw error;
    }
  }, []);

  // VAD: Start auto-recording when voice is detected
  const startListeningMode = useCallback(async () => {
    try {
      const stream = await navigator.mediaDevices.getUserMedia({
        audio: {
          echoCancellation: true,
          noiseSuppression: true,
          autoGainControl: true,
        },
      });
      streamRef.current = stream;

      // Set up audio context for VAD
      const audioContext = new (window.AudioContext || (window as any).webkitAudioContext)();
      const analyser = audioContext.createAnalyser();
      const source = audioContext.createMediaStreamSource(stream);

      analyser.fftSize = 2048;
      analyser.smoothingTimeConstant = 0.8;
      source.connect(analyser);

      audioContextRef.current = audioContext;
      analyserRef.current = analyser;
      isListeningActiveRef.current = true;

      setRecordingState("listening");

      // Voice threshold (adjust based on testing)
      const VOICE_THRESHOLD = 30; // Lower = more sensitive
      const SILENCE_DURATION = 2000; // ms of silence before stopping

      // Start VAD monitoring
      vadIntervalRef.current = setInterval(() => {
        if (!isListeningActiveRef.current) {
          return;
        }

        // Skip VAD check if paused
        if (isListeningPausedRef.current) {
          return;
        }

        const audioLevel = getAudioLevel();

        // Voice detected - start recording if not already recording
        if (audioLevel > VOICE_THRESHOLD && isListeningActiveRef.current && !isRecordingFromVADRef.current) {
          // Notify that voice was detected (for stopping audio playback)
          if (onVoiceDetected) {
            onVoiceDetected();
          }

          isRecordingFromVADRef.current = true;
          silenceScheduledRef.current = false; // Reset silence flag when starting new recording

          // Clear any existing silence timeout
          if (silenceTimeoutRef.current) {
            clearTimeout(silenceTimeoutRef.current);
            silenceTimeoutRef.current = null;
          }

          // Start recording with existing stream
          startRecordingWithStream(stream);
        }

        // Voice continues - cancel silence timeout
        if (audioLevel > VOICE_THRESHOLD && isRecordingFromVADRef.current) {
          // Voice is still active, cancel any scheduled silence timeout
          if (silenceScheduledRef.current) {
            clearTimeout(silenceTimeoutRef.current!);
            silenceTimeoutRef.current = null;
            silenceScheduledRef.current = false;
          }
        }

        // Silence detected - schedule stop ONCE if currently recording
        if (audioLevel <= VOICE_THRESHOLD && isRecordingFromVADRef.current && !silenceScheduledRef.current) {
          silenceScheduledRef.current = true; // Mark that we've scheduled the timeout

          // Schedule stop after silence duration
          silenceTimeoutRef.current = setTimeout(() => {
            if (mediaRecorderRef.current && isRecordingFromVADRef.current) {
              mediaRecorderRef.current.stop();
              isRecordingFromVADRef.current = false;
              silenceScheduledRef.current = false; // Reset for next recording
            }
          }, SILENCE_DURATION);
        }
      }, 100); // Check every 100ms
    } catch (error) {
      isListeningActiveRef.current = false;
      throw error;
    }
  }, [getAudioLevel, stopRecording, startRecordingWithStream]);

  // Stop listening mode
  const stopListeningMode = useCallback(() => {
    // Mark listening as inactive
    isListeningActiveRef.current = false;
    silenceScheduledRef.current = false; // Reset silence flag

    // Clear VAD interval
    if (vadIntervalRef.current) {
      clearInterval(vadIntervalRef.current);
      vadIntervalRef.current = null;
    }

    // Clear silence timeout
    if (silenceTimeoutRef.current) {
      clearTimeout(silenceTimeoutRef.current);
      silenceTimeoutRef.current = null;
    }

    // Stop recording if active
    if (mediaRecorderRef.current && isRecordingFromVADRef.current) {
      mediaRecorderRef.current.stop();
      isRecordingFromVADRef.current = false;
    }

    // Close audio context
    if (audioContextRef.current) {
      audioContextRef.current.close();
      audioContextRef.current = null;
    }

    // Stop all tracks
    if (streamRef.current) {
      streamRef.current.getTracks().forEach((track) => track.stop());
      streamRef.current = null;
    }

    analyserRef.current = null;
    setRecordingState("idle");
  }, []);

  // Pause listening (keeps stream active but stops VAD monitoring)
  const pauseListening = useCallback(() => {
    if (isListeningActiveRef.current && !isListeningPausedRef.current) {
      isListeningPausedRef.current = true;
    }
  }, []);

  // Resume listening (resumes VAD monitoring)
  const resumeListening = useCallback(() => {
    if (isListeningActiveRef.current && isListeningPausedRef.current) {
      isListeningPausedRef.current = false;
    }
  }, []);

  // Cleanup on unmount
  useEffect(() => {
    return () => {
      stopListeningMode();
    };
  }, [stopListeningMode]);

  return {
    recordingState,
    startRecording,
    stopRecording,
    sendRecording,
    cancelRecording,
    startListeningMode,
    stopListeningMode,
    pauseListening,
    resumeListening,
    hasRecording: audioBlob !== null,
    audioContextRef,
    analyserRef,
  };
}

"use client";

import { createContext, useContext, type ReactNode } from "react";

/**
 * Everything the kit needs from your backend, as plain async functions.
 * Leave one out and the matching piece of UI hides itself.
 */
export interface ChatKitAdapters {
  /** Speech to text. Enables the mic button and hands-free mode. */
  transcribe?: (audio: File) => Promise<string>;
  /** Text to speech. Enables the "play" action and spoken replies in hands-free mode. */
  synthesize?: (text: string) => Promise<Blob>;
  /** Follow-up prompts for an assistant message. A `suggestions` data part works too. */
  getSuggestions?: (messageId: string) => Promise<string[]>;
}

export interface Starter {
  title: string;
  label: string;
  prompt: string;
}

export interface ChatKitConfig extends ChatKitAdapters {
  welcome?: { title: string; subtitle?: string };
  starters?: Starter[];
  placeholder?: string;
}

const defaults: ChatKitConfig = {
  welcome: { title: "Hello.", subtitle: "How can I help today?" },
  starters: [],
  placeholder: "Send a message...",
};

const ChatKitContext = createContext<ChatKitConfig>(defaults);

export function ChatKitProvider({
  children,
  ...config
}: ChatKitConfig & { children: ReactNode }) {
  return (
    <ChatKitContext.Provider value={{ ...defaults, ...config }}>
      {children}
    </ChatKitContext.Provider>
  );
}

export function useChatKit() {
  return useContext(ChatKitContext);
}

/**
 * Types for the workflow status and sources UI.
 * Send them to the thread as data parts: `workflow`, `sources`, `suggestions`.
 */

export type NodeStatus = "pending" | "in_progress" | "completed" | "failed" | "cancelled";
export type WorkflowStatus = "idle" | "running" | "succeeded" | "failed" | "stopped" | "canceled";

export interface WorkflowNode {
  id: string;
  title: string;
  type?: string;
  status: NodeStatus;
  elapsedTime?: number;
  error?: string | null;
  inputs?: Record<string, any>;
  outputs?: Record<string, any>;
  executionMetadata?: {
    total_tokens?: number;
    total_price?: string;
    currency?: string;
    error_strategy?: string;
  };
  processData?: {
    usage?: {
      prompt_tokens?: number;
      completion_tokens?: number;
      total_tokens?: number;
      total_price?: string;
      currency?: string;
      latency?: number;
    };
  };
}

export interface WorkflowState {
  workflowRunId: string;
  workflowId?: string;
  status: WorkflowStatus;
  currentNode: WorkflowNode | null;
  nodes: WorkflowNode[];
  totalSteps: number;
  completedSteps: number;
  elapsedTime: number;
  startedAt: number | null;
  finishedAt: number | null;
}

/**
 * A source the answer was grounded on (RAG citation).
 */
export interface Source {
  id: string;
  title: string;
  /** Page URL or bare domain. Used for the favicon and the link. */
  url: string;
  snippet?: string;
  /** Relevance between 0 and 1. */
  score?: number;
}
